[TFMDescription("Converts values to boolean. A string will evaluate to true except for 0, False and No")]
class TFMLogicContextToBoolean extends TFMLogicContextTools
{
}

Method.Source:
public static TFMLogicContextToBoolean Construct()
{
    return new TFMLogicContextToBoolean();
}

protected void new()
{
    super();
    inputTypes.add(TFMLogicContextTypes::String);
    inputTypes.add(TFMLogicContextTypes::Date);
    inputTypes.add(TFMLogicContextTypes::Decimal);
    inputTypes.add(TFMLogicContextTypes::Integer);
    outputType = TFMLogicContextTypes::Boolean;
    noOfInput = 1;
    categories.add("@TFM:TypeConversion");
}

public Object process()
{
    Object ret;


    return ret;
}

public anytype evaluate(TFMLogicContext _context)
{
    anytype         ret;
    SetEnumerator   sEnum;
    TFMCondition    condition;
    str             value;

    if (children == null)
    {
        return true;
    }

    sEnum = children.getEnumerator();

    while (sEnum.moveNext())
    {
        condition = sEnum.current();
        ret = condition.evaluate(_context);
    }

    value = strLwr(any2Str(ret));

    if (value == '' ||
    value == '0' ||
    value == 'false' ||
    value == 'no')
    {
        return false;
    }

    return true;
}
